// -----------------------------------------------------
// Optimized Bouncing Shapes with Fewer Shapes & Faster Rendering
// • Four shape types: balls, blocks, triangles, and ovals.
// • Number of shapes reduced by ~25% (total 27 instead of 36).
// • Each shape is half its previous size.
// • Motion slowed using iTime * 0.25.
// • Orange and teal are biased in the color mix.
// • Collision resolution remains symmetric, with colliding shapes blending toward red.
// • Each shape glows: 1.5× when not colliding, 2.0× when colliding.
// • All shapes are contained within a widescreen rectangle.
// 
// Additional optimizations for speed:
//   - Reduced collision iterations (3 instead of 5).
//   - Reduced raymarch iterations (6 instead of 8).
//   - Reduced total rays from 100 to 50.
// 
// NOTE: In the collision resolution loop, the correction factor has been increased
// from 0.5 to 1.0 so that shapes visibly bounce off each other when they collide.
// -----------------------------------------------------

// ----- Define Shape Counts (Reduced) -----
#define NUM_BALLS     9
#define NUM_BLOCKS    9
#define NUM_TRIANGLES 4
#define NUM_OVALS     5
#define NUM_OBJECTS   (NUM_BALLS + NUM_BLOCKS + NUM_TRIANGLES + NUM_OVALS)

// Global arrays to hold the final (collision–resolved) positions and collision flags.
vec2 simPos[NUM_OBJECTS];
float simCollision[NUM_OBJECTS]; // 1.0 if that object experienced a collision

// ----- SDF Primitives -----
float sdBox(in vec2 p, in vec2 b) {
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float sdCircle(in vec2 p, float radius) {
    return length(p) - radius;
}

// Union operator: returns the shape with the smaller distance.
vec4 opU(vec4 d1, vec4 d2) {
    return (d1.w < d2.w) ? d1 : d2;
}

// ----- Utility Functions -----

// bounceVal: returns a value that “bounces” between -amplitude and +amplitude.
float bounceVal(float t, float period, float amplitude) {
    return amplitude * ((abs(fract(t / period) * 2.0 - 1.0) - 0.5) * 2.0);
}

// rotate2D: rotates a 2D vector by angle a (in radians).
vec2 rotate2D(vec2 p, float a) {
    float ca = cos(a);
    float sa = sin(a);
    return vec2(ca * p.x - sa * p.y, sa * p.x + ca * p.y);
}

// ----- New SDF Functions for Triangle and Oval -----

// SDF for an equilateral triangle of “size” r.
float sdTriangle(vec2 p, float r) {
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0)
        p = vec2(p.x - k * p.y, -k * p.x - p.y) * 0.5;
    return -length(p) * sign(p.y);
}

// SDF for an oval (ellipse) centered at the origin.
// 'r' controls the horizontal and vertical radii.
float sdOval(vec2 p, vec2 r) {
    float k0 = length(p / r);
    float k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}

// ----- Base Position and Effective Radius -----

// Compute each shape’s “natural” bouncing position.
// • iTime is multiplied by 0.25 to slow motion further.
// • Period values remain scaled (×1.25) to increase speed variety.
// • The horizontal coordinate is scaled by iResolution.x/iResolution.y so that the simulation area becomes widescreen.
vec2 basePos(int i) {
    vec2 bp;
    if (i < NUM_BALLS) {
        // Balls
        float phase   = float(i) * 10.0;
        float periodX = (3.0 + mod(float(i), 2.0)) * 1.25;
        float periodY = (4.0 + mod(float(i), 2.0)) * 1.25;
        bp = vec2(
            bounceVal(iTime * 0.25 + phase, periodX, 1.0),
            bounceVal(iTime * 0.25 + phase * 1.1, periodY, 1.0)
        );
    } else if (i < NUM_BALLS + NUM_BLOCKS) {
        // Blocks
        float phase   = float(i - NUM_BALLS) * 20.0;
        float periodX = (2.5 + mod(float(i), 2.0)) * 1.25;
        float periodY = (3.5 + mod(float(i), 2.0)) * 1.25;
        bp = vec2(
            bounceVal(iTime * 0.25 + phase, periodX, 1.0),
            bounceVal(iTime * 0.25 + phase * 1.2, periodY, 1.0)
        );
    } else if (i < NUM_BALLS + NUM_BLOCKS + NUM_TRIANGLES) {
        // Triangles
        float phase   = float(i - (NUM_BALLS + NUM_BLOCKS)) * 30.0;
        float periodX = (3.5 + mod(float(i), 2.0)) * 1.25;
        float periodY = (4.5 + mod(float(i), 2.0)) * 1.25;
        bp = vec2(
            bounceVal(iTime * 0.25 + phase, periodX, 1.0),
            bounceVal(iTime * 0.25 + phase * 1.3, periodY, 1.0)
        );
    } else {
        // Ovals
        float phase   = float(i - (NUM_BALLS + NUM_BLOCKS + NUM_TRIANGLES)) * 40.0;
        float periodX = (2.8 + mod(float(i), 2.0)) * 1.25;
        float periodY = (3.8 + mod(float(i), 2.0)) * 1.25;
        bp = vec2(
            bounceVal(iTime * 0.25 + phase, periodX, 1.0),
            bounceVal(iTime * 0.25 + phase * 1.4, periodY, 1.0)
        );
    }
    bp.x *= iResolution.x / iResolution.y;
    return bp;
}

// Return an effective collision radius for each shape (halved).
float effectiveRadius(int i) {
    if (i < NUM_BALLS) return 0.025;
    else if (i < NUM_BALLS + NUM_BLOCKS) return 0.04;
    else if (i < NUM_BALLS + NUM_BLOCKS + NUM_TRIANGLES) return 0.03;
    else return 0.035; // For ovals.
}

// ----- Object Color with Bias toward Orange and Teal -----
//
// This function computes a base color for each object and then biases it so that
// orange (vec3(1.0, 0.5, 0.0)) and teal (vec3(0.0, 0.5, 0.5)) occur more frequently.
// Finally, if a collision occurred the color blends toward red.
vec3 objectColor(int i) {
    vec3 orig;
    // Use a time–invariant pseudo–random value based on the shape index.
    float rdm = fract(sin(float(i) * 31.4159) * 43758.5453);

    if (i < NUM_BALLS) {
        orig = vec3(0.5 + 0.5 * sin(iTime + float(i) * 1.1),
                    0.5 + 0.5 * cos(iTime + float(i) * 1.3),
                    0.5 + 0.5 * sin(iTime + float(i) * 1.7));
    } else if (i < NUM_BALLS + NUM_BLOCKS) {
        float rnd = fract(sin(float(i) * 12.9898) * 43758.5453);
        orig = vec3(rnd,
                    fract(sin(float(i) * 78.233) * 43758.5453),
                    fract(sin(float(i) * 34.345) * 43758.5453));
    } else if (i < NUM_BALLS + NUM_BLOCKS + NUM_TRIANGLES) {
        orig = vec3(0.5 + 0.5 * sin(iTime + float(i) * 0.8),
                    0.5 + 0.5 * cos(iTime + float(i) * 1.1),
                    0.5 + 0.5 * sin(iTime + float(i) * 1.3));
    } else {
        orig = vec3(0.5 + 0.5 * sin(iTime + float(i) * 0.9),
                    0.5 + 0.5 * cos(iTime + float(i) * 1.2),
                    0.5 + 0.5 * sin(iTime + float(i) * 1.4));
    }

    // Bias: 80% of the time, force the color toward orange or teal.
    vec3 biased = (rdm < 0.4) ? vec3(1.0, 0.5, 0.0)
                 : (rdm < 0.8) ? vec3(0.0, 0.5, 0.5)
                               : orig;
    vec3 baseColor = mix(orig, biased, 0.8);
    return mix(baseColor, vec3(1.0, 0.0, 0.0), simCollision[i]); // Blend toward red on collision.
}

// ----- Scene SDF -----
//
// For each object we compute its SDF based on its type and then apply a glow factor.
// Glow factor: 1.5× (50% brighter) if not colliding, 2.0× (100% brighter) if colliding.
vec4 sdf(vec2 origin) {
    vec4 d = vec4(vec3(0.0), 1e5);
    for (int i = 0; i < NUM_OBJECTS; i++) {
        vec2 pos = simPos[i];
        float dist;
        vec3 col = objectColor(i);
        if (i < NUM_BALLS) {
            // Ball: circle SDF (half size: 0.025).
            dist = sdCircle(origin - pos, 0.025);
        } else if (i < NUM_BALLS + NUM_BLOCKS) {
            // Block: box SDF (half size: vec2(0.035, 0.015)).
            float angle = iTime + float(i);
            vec2 diff = origin - pos;
            diff = rotate2D(diff, angle);
            dist = sdBox(diff, vec2(0.035, 0.015));
        } else if (i < NUM_BALLS + NUM_BLOCKS + NUM_TRIANGLES) {
            // Triangle: SDF (half size: 0.03).
            float angle = iTime + float(i);
            vec2 diff = origin - pos;
            diff = rotate2D(diff, angle);
            dist = sdTriangle(diff, 0.03);
        } else {
            // Oval: SDF (half size: radii vec2(0.04, 0.02)).
            float angle = iTime + float(i);
            vec2 diff = origin - pos;
            diff = rotate2D(diff, angle);
            dist = sdOval(diff, vec2(0.04, 0.02));
        }
        float glowFactor = mix(1.5, 2.0, simCollision[i]);
        d = opU(d, vec4(col * glowFactor, dist));
    }
    return d;
}

// ----- Raymarching and Radiance -----

// Cast a ray from the origin in the given direction.
// Reduced iterations: 6 instead of 8.
vec4 castRay(vec2 origin, vec2 direction) {
    float t = 0.0;
    for (int i = 0; i < 6; i++) {
        vec4 s = sdf(origin + t * direction);
        if (s.w < 0.01)
            return vec4(s.rgb, 1.0);
        t += s.w;
        if (t > 4.0)
            break;
    }
    return vec4(0.0);
}

// Cast fewer rays for performance.
vec3 radiance(vec2 origin) {
    int ray_count = 50;  // Reduced from 100.
    vec3 sum = vec3(0.0);
    for (int i = 0; i < ray_count; i++) {
        float angle = (float(i) / float(ray_count)) * 6.28318;
        vec2 dir = vec2(sin(angle), cos(angle));
        sum += castRay(origin, dir).rgb;
    }
    return sum / float(ray_count);
}

// ----- Tone Mapping -----
vec3 ACESFitted(vec3 x) {
    const float a = 2.51;
    const float b = 0.03;
    const float c = 2.43;
    const float d = 0.59;
    const float e = 0.14;
    return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

vec3 linear_srgb(vec3 color) {
    return color;
}

// ----- Main Image Function -----
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Precompute base positions and initialize collision flags.
    vec2 pos[NUM_OBJECTS];
    for (int i = 0; i < NUM_OBJECTS; i++) {
        pos[i] = basePos(i);
        simCollision[i] = 0.0;
    }

    // --- Symmetric Collision Resolution ---
    const int COLL_ITER = 3;  // Reduced from 5.
    for (int iter = 0; iter < COLL_ITER; iter++) {
        for (int i = 0; i < NUM_OBJECTS; i++) {
            for (int j = i + 1; j < NUM_OBJECTS; j++) {
                vec2 diff = pos[i] - pos[j];
                float d = length(diff);
                float r_i = effectiveRadius(i);
                float r_j = effectiveRadius(j);
                float minDist = r_i + r_j;
                if (d < minDist && d > 0.001) {
                    // Increased correction factor: multiply by 1.0 instead of 0.5.
                    vec2 correction = normalize(diff) * (minDist - d);
                    pos[i] += correction;
                    pos[j] -= correction;
                    simCollision[i] = 1.0;
                    simCollision[j] = 1.0;
                }
            }
        }
    }
    for (int i = 0; i < NUM_OBJECTS; i++) {
        simPos[i] = pos[i];
    }

    // Map fragCoord to normalized widescreen coordinates.
    vec2 uv = (-iResolution.xy + 2.0 * fragCoord) / iResolution.y;
    vec3 color = radiance(uv);

    // Apply tone mapping.
    color = ACESFitted(color);
    color = linear_srgb(color);

    fragColor = vec4(color, 1.0);
}
